```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The contract's `requires len(text) <= 100000` holds of every input,
        // so the text is forwarded to the channel unchanged.
        let confirmation = response_channel::send(&reply.text);

        // The session identity and the delivery flag are the host channel's to
        // report; this node never fabricates them. If the channel did not
        // accept the message, or did not stamp a session, there is no output
        // that satisfies the `ensures` clauses, so the node traps instead of
        // producing one.
        if !confirmation.delivered || confirmation.session.is_empty() {
            panic!("response channel did not confirm delivery");
        }

        confirmation
    }
}

export!(Node);
